/*
 * Offline QR Code generator (byte mode) for FixedFloat order pages.
 * Based on Project Nayuki's QR Code generator (MIT License).
 * No external network dependency: encodes text to a QR matrix and paints it
 * to a canvas, returning a PNG data URL. Used to render the send-wallet QR.
 */
(function (global) {
	'use strict';

	// ---- Reed-Solomon / GF(256) helpers ----
	function ReedSolomonComputeDivisor(degree) {
		if (degree < 1 || degree > 255) throw new RangeError('Degree out of range');
		var result = [];
		for (var i = 0; i < degree - 1; i++) result.push(0);
		result.push(1); // Monomial x^0
		var root = 1;
		for (var i = 0; i < degree; i++) {
			for (var j = 0; j < result.length; j++) {
				result[j] = ReedSolomonMultiply(result[j], root);
				if (j + 1 < result.length) result[j] ^= result[j + 1];
			}
			root = ReedSolomonMultiply(root, 0x02);
		}
		return result;
	}

	function ReedSolomonComputeRemainder(data, divisor) {
		var result = divisor.map(function () { return 0; });
		data.forEach(function (b) {
			var factor = b ^ result.shift();
			result.push(0);
			divisor.forEach(function (coef, i) {
				result[i] ^= ReedSolomonMultiply(coef, factor);
			});
		});
		return result;
	}

	function ReedSolomonMultiply(x, y) {
		if (x >>> 8 !== 0 || y >>> 8 !== 0) throw new RangeError('Byte out of range');
		var z = 0;
		for (var i = 7; i >= 0; i--) {
			z = (z << 1) ^ ((z >>> 7) * 0x11D);
			z ^= ((y >>> i) & 1) * x;
		}
		return z;
	}

	// ---- Error correction level ----
	var Ecc = {
		LOW:      { ordinal: 0, formatBits: 1 },
		MEDIUM:   { ordinal: 1, formatBits: 0 },
		QUARTILE: { ordinal: 2, formatBits: 3 },
		HIGH:     { ordinal: 3, formatBits: 2 }
	};

	// Per-version tables (index by version 1..40; index 0 unused; index by ECC ordinal)
	var ECC_CODEWORDS_PER_BLOCK = [
		[-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
		[-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28],
		[-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
		[-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30]
	];
	var NUM_ERROR_CORRECTION_BLOCKS = [
		[-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25],
		[-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49],
		[-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68],
		[-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81]
	];

	function getNumRawDataModules(ver) {
		if (ver < 1 || ver > 40) throw new RangeError('Version out of range');
		var result = (16 * ver + 128) * ver + 64;
		if (ver >= 2) {
			var numAlign = Math.floor(ver / 7) + 2;
			result -= (25 * numAlign - 10) * numAlign - 55;
			if (ver >= 7) result -= 36;
		}
		return result;
	}

	function getNumDataCodewords(ver, ecc) {
		return Math.floor(getNumRawDataModules(ver) / 8)
			- ECC_CODEWORDS_PER_BLOCK[ecc.ordinal][ver]
			* NUM_ERROR_CORRECTION_BLOCKS[ecc.ordinal][ver];
	}

	// ---- Encode text (UTF-8 byte mode) ----
	function toUtf8Bytes(str) {
		var utf8 = unescape(encodeURIComponent(str));
		var bytes = [];
		for (var i = 0; i < utf8.length; i++) bytes.push(utf8.charCodeAt(i));
		return bytes;
	}

	function appendBits(val, len, bb) {
		if (len < 0 || len > 31 || (val >>> len) !== 0) throw new RangeError('Value out of range');
		for (var i = len - 1; i >= 0; i--) bb.push((val >>> i) & 1);
	}

	// ---- Build the QR matrix ----
	function QrCode(version, ecc, dataCodewords, mask) {
		this.version = version;
		this.ecc = ecc;
		this.size = version * 4 + 17;
		this.modules = [];
		this.isFunction = [];
		var row;
		for (var i = 0; i < this.size; i++) {
			row = [];
			for (var j = 0; j < this.size; j++) row.push(false);
			this.modules.push(row.slice());
			this.isFunction.push(row.slice());
		}
		this.drawFunctionPatterns();
		var allCodewords = this.addEccAndInterleave(dataCodewords);
		this.drawCodewords(allCodewords);
		if (mask < 0) {
			var minPenalty = Infinity;
			for (var m = 0; m < 8; m++) {
				this.applyMask(m);
				this.drawFormatBits(m);
				var penalty = this.getPenaltyScore();
				if (penalty < minPenalty) { mask = m; minPenalty = penalty; }
				this.applyMask(m); // undo
			}
		}
		this.mask = mask;
		this.applyMask(mask);
		this.drawFormatBits(mask);
	}

	QrCode.prototype.getModule = function (x, y) {
		return 0 <= x && x < this.size && 0 <= y && y < this.size && this.modules[y][x];
	};

	QrCode.prototype.setFunctionModule = function (x, y, isDark) {
		this.modules[y][x] = isDark;
		this.isFunction[y][x] = true;
	};

	QrCode.prototype.drawFunctionPatterns = function () {
		var i;
		for (i = 0; i < this.size; i++) {
			this.setFunctionModule(6, i, i % 2 === 0);
			this.setFunctionModule(i, 6, i % 2 === 0);
		}
		this.drawFinderPattern(3, 3);
		this.drawFinderPattern(this.size - 4, 3);
		this.drawFinderPattern(3, this.size - 4);
		var alignPatPos = this.getAlignmentPatternPositions();
		var numAlign = alignPatPos.length;
		for (i = 0; i < numAlign; i++) {
			for (var j = 0; j < numAlign; j++) {
				if (!((i === 0 && j === 0) || (i === 0 && j === numAlign - 1) || (i === numAlign - 1 && j === 0)))
					this.drawAlignmentPattern(alignPatPos[i], alignPatPos[j]);
			}
		}
		this.drawFormatBits(0);
		this.drawVersion();
	};

	QrCode.prototype.drawFinderPattern = function (x, y) {
		for (var dy = -4; dy <= 4; dy++) {
			for (var dx = -4; dx <= 4; dx++) {
				var dist = Math.max(Math.abs(dx), Math.abs(dy));
				var xx = x + dx, yy = y + dy;
				if (0 <= xx && xx < this.size && 0 <= yy && yy < this.size)
					this.setFunctionModule(xx, yy, dist !== 2 && dist !== 4);
			}
		}
	};

	QrCode.prototype.drawAlignmentPattern = function (x, y) {
		for (var dy = -2; dy <= 2; dy++)
			for (var dx = -2; dx <= 2; dx++)
				this.setFunctionModule(x + dx, y + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
	};

	QrCode.prototype.getAlignmentPatternPositions = function () {
		if (this.version === 1) return [];
		var numAlign = Math.floor(this.version / 7) + 2;
		var step = (this.version === 32) ? 26 :
			Math.ceil((this.version * 4 + 4) / (numAlign * 2 - 2)) * 2;
		var result = [6];
		for (var pos = this.size - 7; result.length < numAlign; pos -= step)
			result.splice(1, 0, pos);
		return result;
	};

	QrCode.prototype.drawFormatBits = function (mask) {
		var data = (this.ecc.formatBits << 3) | mask;
		var rem = data;
		for (var i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
		var bits = ((data << 10) | rem) ^ 0x5412;
		var i2;
		for (i2 = 0; i2 <= 5; i2++) this.setFunctionModule(8, i2, getBit(bits, i2));
		this.setFunctionModule(8, 7, getBit(bits, 6));
		this.setFunctionModule(8, 8, getBit(bits, 7));
		this.setFunctionModule(7, 8, getBit(bits, 8));
		for (i2 = 9; i2 < 15; i2++) this.setFunctionModule(14 - i2, 8, getBit(bits, i2));
		for (i2 = 0; i2 < 8; i2++) this.setFunctionModule(this.size - 1 - i2, 8, getBit(bits, i2));
		for (i2 = 8; i2 < 15; i2++) this.setFunctionModule(8, this.size - 15 + i2, getBit(bits, i2));
		this.setFunctionModule(8, this.size - 8, true);
	};

	QrCode.prototype.drawVersion = function () {
		if (this.version < 7) return;
		var rem = this.version;
		for (var i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1F25);
		var bits = (this.version << 12) | rem;
		for (var i2 = 0; i2 < 18; i2++) {
			var color = getBit(bits, i2);
			var a = this.size - 11 + (i2 % 3);
			var b = Math.floor(i2 / 3);
			this.setFunctionModule(a, b, color);
			this.setFunctionModule(b, a, color);
		}
	};

	QrCode.prototype.addEccAndInterleave = function (data) {
		var ver = this.version, ecc = this.ecc;
		var numBlocks = NUM_ERROR_CORRECTION_BLOCKS[ecc.ordinal][ver];
		var blockEccLen = ECC_CODEWORDS_PER_BLOCK[ecc.ordinal][ver];
		var rawCodewords = Math.floor(getNumRawDataModules(ver) / 8);
		var numShortBlocks = numBlocks - rawCodewords % numBlocks;
		var shortBlockLen = Math.floor(rawCodewords / numBlocks);
		var blocks = [];
		var rsDiv = ReedSolomonComputeDivisor(blockEccLen);
		var k = 0;
		for (var i = 0; i < numBlocks; i++) {
			var datLen = shortBlockLen - blockEccLen + (i < numShortBlocks ? 0 : 1);
			var dat = data.slice(k, k + datLen);
			k += datLen;
			var eccBytes = ReedSolomonComputeRemainder(dat, rsDiv);
			if (i < numShortBlocks) dat.push(0);
			blocks.push(dat.concat(eccBytes));
		}
		var result = [];
		for (var j = 0; j < blocks[0].length; j++) {
			for (var i2 = 0; i2 < blocks.length; i2++) {
				if (j !== shortBlockLen - blockEccLen || i2 >= numShortBlocks)
					result.push(blocks[i2][j]);
			}
		}
		return result;
	};

	QrCode.prototype.drawCodewords = function (data) {
		var i = 0;
		for (var right = this.size - 1; right >= 1; right -= 2) {
			if (right === 6) right = 5;
			for (var vert = 0; vert < this.size; vert++) {
				for (var j = 0; j < 2; j++) {
					var x = right - j;
					var upward = ((right + 1) & 2) === 0;
					var y = upward ? this.size - 1 - vert : vert;
					if (!this.isFunction[y][x] && i < data.length * 8) {
						this.modules[y][x] = getBit(data[i >>> 3], 7 - (i & 7));
						i++;
					}
				}
			}
		}
	};

	QrCode.prototype.applyMask = function (mask) {
		for (var y = 0; y < this.size; y++) {
			for (var x = 0; x < this.size; x++) {
				var invert;
				switch (mask) {
					case 0: invert = (x + y) % 2 === 0; break;
					case 1: invert = y % 2 === 0; break;
					case 2: invert = x % 3 === 0; break;
					case 3: invert = (x + y) % 3 === 0; break;
					case 4: invert = (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0; break;
					case 5: invert = (x * y) % 2 + (x * y) % 3 === 0; break;
					case 6: invert = ((x * y) % 2 + (x * y) % 3) % 2 === 0; break;
					case 7: invert = ((x + y) % 2 + (x * y) % 3) % 2 === 0; break;
					default: throw new Error('Bad mask');
				}
				if (!this.isFunction[y][x] && invert) this.modules[y][x] = !this.modules[y][x];
			}
		}
	};

	QrCode.prototype.getPenaltyScore = function () {
		var result = 0, size = this.size, m = this.modules;
		var x, y, runColor, runX, runY, i;
		// Rows
		for (y = 0; y < size; y++) {
			runColor = false; runX = 0;
			var runHistory = [0, 0, 0, 0, 0, 0, 0];
			for (x = 0; x < size; x++) {
				if (m[y][x] === runColor) {
					runX++;
					if (runX === 5) result += 3;
					else if (runX > 5) result++;
				} else {
					this.finderPenaltyAddHistory(runX, runHistory);
					if (!runColor) result += this.finderPenaltyCountPatterns(runHistory) * 40;
					runColor = m[y][x]; runX = 1;
				}
			}
			result += this.finderPenaltyTerminateAndCount(runColor, runX, runHistory) * 40;
		}
		// Columns
		for (x = 0; x < size; x++) {
			runColor = false; runY = 0;
			var runHistory2 = [0, 0, 0, 0, 0, 0, 0];
			for (y = 0; y < size; y++) {
				if (m[y][x] === runColor) {
					runY++;
					if (runY === 5) result += 3;
					else if (runY > 5) result++;
				} else {
					this.finderPenaltyAddHistory(runY, runHistory2);
					if (!runColor) result += this.finderPenaltyCountPatterns(runHistory2) * 40;
					runColor = m[y][x]; runY = 1;
				}
			}
			result += this.finderPenaltyTerminateAndCount(runColor, runY, runHistory2) * 40;
		}
		// 2x2 blocks
		for (y = 0; y < size - 1; y++) {
			for (x = 0; x < size - 1; x++) {
				var c = m[y][x];
				if (c === m[y][x + 1] && c === m[y + 1][x] && c === m[y + 1][x + 1]) result += 3;
			}
		}
		// Balance
		var dark = 0;
		for (y = 0; y < size; y++) for (x = 0; x < size; x++) if (m[y][x]) dark++;
		var total = size * size;
		var k = Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1;
		result += k * 10;
		return result;
	};

	QrCode.prototype.finderPenaltyCountPatterns = function (rh) {
		var n = rh[1];
		var core = n > 0 && rh[2] === n && rh[3] === n * 3 && rh[4] === n && rh[5] === n;
		return (core && rh[0] >= n * 4 && rh[6] >= n ? 1 : 0)
			+ (core && rh[6] >= n * 4 && rh[0] >= n ? 1 : 0);
	};

	QrCode.prototype.finderPenaltyTerminateAndCount = function (currentRunColor, currentRunLength, rh) {
		if (currentRunColor) {
			this.finderPenaltyAddHistory(currentRunLength, rh);
			currentRunLength = 0;
		}
		currentRunLength += this.size;
		this.finderPenaltyAddHistory(currentRunLength, rh);
		return this.finderPenaltyCountPatterns(rh);
	};

	QrCode.prototype.finderPenaltyAddHistory = function (currentRunLength, rh) {
		if (rh[0] === 0) currentRunLength += this.size;
		rh.pop();
		rh.unshift(currentRunLength);
	};

	function getBit(x, i) { return ((x >>> i) & 1) !== 0; }

	// ---- Public: encode text -> QrCode ----
	function encodeText(text, ecc) {
		var bytes = toUtf8Bytes(text);
		var bb = [];
		// choose smallest version that fits (byte mode)
		var version;
		for (version = 1; version <= 40; version++) {
			var capacityBits = getNumDataCodewords(version, ecc) * 8;
			var ccBits = version < 10 ? 8 : 16;
			var usedBits = 4 + ccBits + bytes.length * 8;
			if (usedBits <= capacityBits) break;
			if (version === 40) throw new RangeError('Data too long');
		}
		var ccBits = version < 10 ? 8 : 16;
		appendBits(0x4, 4, bb);              // byte mode indicator
		appendBits(bytes.length, ccBits, bb); // char count
		bytes.forEach(function (b) { appendBits(b, 8, bb); });

		var dataCapacityBits = getNumDataCodewords(version, ecc) * 8;
		appendBits(0, Math.min(4, dataCapacityBits - bb.length), bb); // terminator
		appendBits(0, (8 - bb.length % 8) % 8, bb);                    // byte align
		for (var padByte = 0xEC; bb.length < dataCapacityBits; padByte ^= 0xEC ^ 0x11)
			appendBits(padByte, 8, bb);

		var dataCodewords = [];
		for (var i = 0; i < bb.length; i += 8) {
			var b = 0;
			for (var j = 0; j < 8; j++) b = (b << 1) | bb[i + j];
			dataCodewords.push(b);
		}
		return new QrCode(version, ecc, dataCodewords, -1);
	}

	// ---- Render to canvas / data URL ----
	function toCanvas(text, opts) {
		opts = opts || {};
		var eccLevel = Ecc[(opts.ecc || 'MEDIUM').toUpperCase()] || Ecc.MEDIUM;
		var qr = encodeText(String(text), eccLevel);
		var border = opts.border == null ? 4 : opts.border;
		var targetPx = opts.size || 256;
		var count = qr.size + border * 2;
		var scale = Math.max(1, Math.floor(targetPx / count));
		var dim = count * scale;
		var canvas = document.createElement('canvas');
		canvas.width = dim; canvas.height = dim;
		var ctx = canvas.getContext('2d');
		ctx.fillStyle = opts.light || '#ffffff';
		ctx.fillRect(0, 0, dim, dim);
		ctx.fillStyle = opts.dark || '#000000';
		for (var y = 0; y < qr.size; y++) {
			for (var x = 0; x < qr.size; x++) {
				if (qr.modules[y][x]) {
					ctx.fillRect((x + border) * scale, (y + border) * scale, scale, scale);
				}
			}
		}
		return canvas;
	}

	function toDataURL(text, opts) {
		return toCanvas(text, opts).toDataURL('image/png');
	}

	global.QRCodeGen = {
		encodeText: encodeText,
		toCanvas: toCanvas,
		toDataURL: toDataURL,
		Ecc: Ecc
	};
})(typeof window !== 'undefined' ? window : this);
